// ── Factorial — base case + recursive case ───────────────────────
function factorial(n) {
  if (n <= 1) return 1;          // base case
  return n * factorial(n - 1);   // recursive case — shrinks n each time
}
console.log(factorial(5)); // 120

// ── Fibonacci — naive O(2^n) ─────────────────────────────────────
function fibNaive(n) {
  if (n <= 1) return n;          // base cases: fib(0)=0, fib(1)=1
  return fibNaive(n - 1) + fibNaive(n - 2);
}
console.log(fibNaive(10)); // 55

// ── Fibonacci — memoized O(n) ────────────────────────────────────
function fibMemo(n, memo = {}) {
  if (n in memo) return memo[n]; // return cached result
  if (n <= 1) return n;
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}
console.log(fibMemo(40)); // 102334155 — instant

// ── Tree traversal — recursion's home turf ───────────────────────
function sumTree(node) {
  if (!node) return 0;           // base case: null node
  return node.value + sumTree(node.left) + sumTree(node.right);
}
const tree = {
  value: 1,
  left:  { value: 2, left: null, right: null },
  right: { value: 3, left: null, right: null }
};
console.log(sumTree(tree)); // 6

// ── Recursion vs. Iteration ──────────────────────────────────────
function factRecursive(n) {
  if (n <= 1) return 1;
  return n * factRecursive(n - 1); // O(n) stack frames
}

function factIterative(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i; // O(1) extra space
  return result;
}

console.log(factRecursive(6)); // 720
console.log(factIterative(6)); // 720 — same result, no stack growth

// ── Tail-call form (concept — V8 does NOT apply TCO) ─────────────
function factTail(n, acc = 1) {
  if (n <= 1) return acc;
  return factTail(n - 1, n * acc); // last op is the call — a tail call
  // A TCO runtime would reuse the same frame; V8 does not
}
